// === Helpers ===
function box(x1,y1,z1,x2,y2,z2,t){
  const X1=Math.max(0,Math.min(x1,x2)),X2=Math.min(255,Math.max(x1,x2));
  const Y1=Math.max(0,Math.min(y1,y2)),Y2=Math.min(255,Math.max(y1,y2));
  const Z1=Math.max(0,Math.min(z1,z2)),Z2=Math.min(255,Math.max(z1,z2));
  if(X1>X2||Y1>Y2||Z1>Z2)return;
  for(let x=X1;x<=X2;x++)for(let y=Y1;y<=Y2;y++)for(let z=Z1;z<=Z2;z++)block(x,y,z,t);
}
function line(x1,y1,z1,x2,y2,z2,t){
  const dx=x2-x1,dy=y2-y1,dz=z2-z1,n=Math.max(Math.abs(dx),Math.abs(dy),Math.abs(dz));
  for(let i=0;i<=n;i++){const f=i/n;block(Math.round(x1+dx*f),Math.round(y1+dy*f),Math.round(z1+dz*f),t);}
}
function sphere(cx,cy,cz,r,t){
  const r2=r*r;
  for(let x=cx-r;x<=cx+r;x++)for(let y=cy-r;y<=cy+r;y++)for(let z=cz-r;z<=cz+r;z++){
    if((x-cx)**2+(y-cy)**2+(z-cz)**2<=r2)block(x,y,z,t);
  }
}

