// Trees
function tree(tx,tz){
  const h=6+Math.floor(rng()*5);
  box(tx,6,tz,tx,6+h,tz,'oak_log');
  // Foliage layers
  for(let dy=h;dy>=h-5;dy--){
    const r=3+Math.floor(rng()*2);
    for(let dx=-r;dx<=r;dx++)for(let dz=-r;dz<=r;dz++){
      if(Math.abs(dx)+Math.abs(dz)<=r+1&&rng()>0.15)block(tx+dx,6+dy,tz+dz,'oak_leaves');
    }
  }
  // Top cap
  block(tx,6+h+1,tz,'oak_leaves');
}

